<?php
declare(strict_types=1);
putenv('RUMOHUB_ENABLED=0');putenv('RUMOHUB_BENEFITS=0');putenv('RUMO10_WORLD_CALENDAR=1');putenv('RUMO10_WORLD_FIXTURES=1');require dirname(__DIR__).'/app/bootstrap.php';
$root=dirname(__DIR__);$out=$root.'/Docs/mundializacao-v07/classificatorias-estaduais';if(!is_dir($out))mkdir($out,0777,true);
$catalog=Competition::catalog();$trial=AlagoasTrial::create(855000);foreach($trial['world_reference'] as $id=>$pin)$catalog[$id]=$pin['definition'];
$r=json_decode(file_get_contents($root.'/database/competition-references/br-d-admission-2026-v2.json'),true,512,JSON_THROW_ON_ERROR);$rows=[];
foreach($r['federation_ranking'] as $uf=>$rank){$records=[];foreach($catalog as $id=>$c){$state=$c['uf']??strtoupper(substr($id,0,2));if($state!==$uf||!in_array($c['family']??'', ['state','sp'],true)&&!str_starts_with($id,'sp-'))continue;
 $records[]=['id'=>$id,'name'=>$c['name'],'edition'=>$c['edition']??null,'format'=>$c['format'],'participants'=>count($c['teams']),'sources'=>$c['verified_sources']??[$c['source']??null],'validation'=>$uf==='AL'?'pinned_pilot_sports_verified':'catalogue_reference_not_D_qualification_certification','can_generate_legacy_results'=>true];}
 $path=StateQualification::policies()[$uf]??null;$rows[]=['uf'=>$uf,'rnf_reference_2026'=>$rank,'quota'=>$r['quotas']['federation:'.$uf],'qualifying_competition'=>$path['competition']??'not_certified','rule_source'=>$path['source']??null,'location'=>$path['location']??null,'path_status'=>$path?'sports_path_implemented_pending_national_admission':'blocked_pending_primary_rule_and_participants_review','usable_final_classification'=>$path?'verified_reconstruction_required':'legacy_result_not_certified_for_D','specific_engine'=>$path?'existing_alagoas_adapter_reused':'review_required; generic_format_does_not_prove_REC','lower_or_selective'=>$path?'not_required_for_AL_D_path; lower_division_affects_next_state_edition':'official_qualifying_path_and_selective_permissions_unverified','roll_down'=>$path?$path['roll_down']:'not_activated_without_official_path','national_entries_granted'=>0,'competitions'=>$records];}
file_put_contents($out.'/federations.json',json_encode(['source_quota'=>$r['sources'],'knowledge'=>'2026 quota reference; future freeze is simulated adaptation','rows'=>$rows],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
$f=fopen($out.'/federations.csv','w');fwrite($f,"\xEF\xBB\xBF");$keys=['uf','rnf_reference_2026','quota','qualifying_competition','rule_source','location','path_status','usable_final_classification','specific_engine','lower_or_selective','roll_down','national_entries_granted'];fputcsv($f,$keys,',','"','');foreach($rows as $row)fputcsv($f,array_map(fn($key)=>$row[$key],$keys),',','"','');fclose($f);
echo 'OK: '.count($rows).' federações; '.array_sum(array_column($rows,'quota'))." vagas; nenhum cadastro alterado.\n";
